// Parser RSS 2.0 regex-based per Gazzetta Ufficiale (Serie Generale).
// Estrae i 5 item piu recenti e li normalizza nello shape canonico FedShield.
const crypto = require('crypto');
const raw = $input.first().json.data || $input.first().json.body || $input.first().json;
const xml = typeof raw === 'string' ? raw : JSON.stringify(raw);
const MAX_ITEMS = 5;
const SOURCE_NAME = 'Normattiva GU (Serie Generale)';

function stripCdata(s) {
  if (!s) return '';
  return String(s).replace(/^\s*<!\[CDATA\[/, '').replace(/\]\]>\s*$/, '').trim();
}
function decodeEntities(s) {
  return String(s || '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
}
function extractTag(block, tag) {
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const m = block.match(re);
  return m ? decodeEntities(stripCdata(m[1])).trim() : '';
}

const itemRe = /<item\b[^>]*>([\s\S]*?)<\/item>/gi;
const out = [];
let match;
let count = 0;
while ((match = itemRe.exec(xml)) !== null && count < MAX_ITEMS) {
  const block = match[1];
  const title = extractTag(block, 'title');
  const link = extractTag(block, 'link');
  const pubDate = extractTag(block, 'pubDate');
  const contentEncoded = extractTag(block, 'content:encoded') || extractTag(block, 'description');
  if (!title) continue;
  const hashInput = title + '|' + pubDate;
  const contentHash = crypto.createHash('sha256').update(hashInput).digest('hex');
  out.push({
    json: {
      sourceName: SOURCE_NAME,
      normTitle: title,
      normReference: title,
      normText: contentEncoded || title,
      changeSummary: contentEncoded ? contentEncoded.slice(0, 500) : title,
      fetchedAt: new Date().toISOString(),
      contentHash,
      link
    }
  });
  count++;
}
return out;

// Parser RSS 2.0 regex-based per EUR-Lex (Official Journal L series, lingua IT).
// Estrae i 5 item piu recenti e li normalizza nello shape canonico FedShield.
const crypto = require('crypto');
const raw = $input.first().json.data || $input.first().json.body || $input.first().json;
const xml = typeof raw === 'string' ? raw : JSON.stringify(raw);
const MAX_ITEMS = 5;
const SOURCE_NAME = 'EUR-Lex (OJ L, IT)';

function stripCdata(s) {
  if (!s) return '';
  return String(s).replace(/^\s*<!\[CDATA\[/, '').replace(/\]\]>\s*$/, '').trim();
}
function decodeEntities(s) {
  return String(s || '')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
}
function extractTag(block, tag) {
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const m = block.match(re);
  return m ? decodeEntities(stripCdata(m[1])).trim() : '';
}
function extractCelex(title) {
  const m = String(title || '').match(/CELEX:([A-Z0-9()]+)/i);
  return m ? m[1] : '';
}

const itemRe = /<item\b[^>]*>([\s\S]*?)<\/item>/gi;
const out = [];
let match;
let count = 0;
while ((match = itemRe.exec(xml)) !== null && count < MAX_ITEMS) {
  const block = match[1];
  const title = extractTag(block, 'title');
  const link = extractTag(block, 'link');
  const pubDate = extractTag(block, 'pubDate');
  const description = extractTag(block, 'description');
  if (!title) continue;
  const celex = extractCelex(title);
  const hashInput = title + '|' + pubDate;
  const contentHash = crypto.createHash('sha256').update(hashInput).digest('hex');
  out.push({
    json: {
      sourceName: SOURCE_NAME,
      normTitle: title,
      normReference: celex || title,
      normText: description || title,
      changeSummary: description ? description.slice(0, 500) : title,
      fetchedAt: new Date().toISOString(),
      contentHash,
      link
    }
  });
  count++;
}
return out;

// Dedup persistente: ricorda gli hash gia visti tra esecuzioni via
// getWorkflowStaticData('global'). Mantiene al massimo 500 hash recenti.
// NOTA: INAIL e' temporaneamente skippato — il portale espone solo un feed RSS
// generale di eventi (https://www.inail.it/portale/it/rss.xml) e non un feed
// dedicato alle circolari. TODO: scraping HTML della pagina circolari quando
// il team accetta la fragilita' o INAIL pubblichera un feed dedicato.
const staticData = $getWorkflowStaticData('global');
const seen = Array.isArray(staticData.seenHashes) ? staticData.seenHashes : [];
const seenSet = new Set(seen);
const items = $input.all();
const fresh = [];
for (const it of items) {
  const j = it.json || {};
  const h = j.contentHash;
  if (!h) continue;
  if (seenSet.has(h)) continue;
  seenSet.add(h);
  fresh.push({ json: j });
}
const MAX_REMEMBER = 500;
const updated = Array.from(seenSet);
staticData.seenHashes = updated.slice(Math.max(0, updated.length - MAX_REMEMBER));
staticData.lastRunAt = new Date().toISOString();
if (fresh.length === 0) {
  return [{ json: { _empty: true, info: 'Nessun nuovo documento normativo' } }];
}
return fresh;

const p = $input.first().json;
if (p._empty) {
  return [{ json: { _skip: true, proposal: null, systemPrompt: '', userPrompt: '' } }];
}
const proposal = {
  sourceName: p.sourceName,
  normTitle: p.normTitle,
  normReference: p.normReference,
  normText: p.normText,
  changeSummary: p.changeSummary,
  contentHash: p.contentHash
};
const systemPrompt = `Sei un esperto normativo HSE italiano. Analizza il testo normativo qui sotto e identifica TUTTI i nuovi/modificati obblighi per le checklist di sicurezza sul lavoro o igiene alimentare. Rispondi in JSON strict con la forma:\n{\"changes\": [{\"checklistType\": \"safety|haccp|both\", \"area\": \"string\", \"question\": \"string\", \"severity\": 1-4, \"sanctionable\": true|false}]}\nNessun campo extra, no preambolo, solo JSON.`;
const userPrompt = `TITOLO: ${proposal.normTitle}\nRIFERIMENTO: ${proposal.normReference}\nTESTO: ${proposal.normText}\nSINTESI CAMBIO: ${proposal.changeSummary}`;
return [{ json: { systemPrompt, userPrompt, proposal } }];

const aiResp = $input.first().json || {};
const content = aiResp.choices && aiResp.choices[0] && aiResp.choices[0].message ? aiResp.choices[0].message.content : '';
let parsed = { changes: [] };
try { parsed = JSON.parse(String(content || '{}')); } catch (e) { /* ignore */ }
const changes = Array.isArray(parsed.changes) ? parsed.changes : [];
const proposal = $items('Build AI Prompt')[0].json.proposal;
const payload = {
  sourceName: proposal.sourceName,
  normTitle: proposal.normTitle,
  normReference: proposal.normReference,
  normText: proposal.normText,
  changeSummary: proposal.changeSummary,
  proposedChanges: changes,
  contentHash: proposal.contentHash
};
return [{ json: { payload, hasChanges: changes.length > 0 } }];
